// ============ StudyBridge_QA_Health_Check :: Normalize Health Result ============
// L1 read-only health + SSE route-presence DRIFT check (NOT transport execution).
function grab(name){ try { return $(name).item.json; } catch(e){ return null; } }

function svc(name, label, url){
  const r = grab(name);
  const sc = r ? (r.statusCode || (r.body && r.body.statusCode) || 0) : 0;
  const reachable = !!r;
  const statusOk = sc >= 200 && sc < 400;
  return { service: label, url, statusCode: sc, alive: statusOk, http2xx3xx: statusOk, unreachable: !reachable };
}

// ---- Core layers ----
const web      = svc('Check StudyBridge Web','web','https://www.studybridge.co.kr');
const fastapi  = svc('Check FastAPI Health','fastapi','http://127.0.0.1:8000/health');
const springApiR = grab('Check Spring API Health');
const springAct  = svc('Check Spring Actuator Health','spring_actuator','https://www.studybridge.co.kr/actuator/health');

// Spring API: 401/403 = auth-blocked (alive), 404 = endpoint not found
const spApiSc = springApiR ? (springApiR.statusCode || 0) : 0;
const springApiAuthBlocked = spApiSc === 401 || spApiSc === 403;
const springApiEndpointNotFound = spApiSc === 404;
const springApiAlive = (spApiSc >= 200 && spApiSc < 400) || springApiAuthBlocked;

const springAlive = springAct.alive || springApiAlive;

// n8n self health
const n8nR = grab('Check n8n Health');
const n8nSc = n8nR ? (n8nR.statusCode || 0) : 0;
let n8nStatusOk = n8nSc >= 200 && n8nSc < 400;
try { const nb = n8nR && n8nR.body; if (nb && typeof nb==='object' && nb.status && String(nb.status).toLowerCase()==='ok') n8nStatusOk = true; } catch(e){}
const n8nAlive = n8nStatusOk;

// Ollama
const ovR = grab('Check Ollama Version');
const otR = grab('Check Ollama Tags');
const ovSc = ovR ? (ovR.statusCode || 0) : 0;
const otSc = otR ? (otR.statusCode || 0) : 0;
const ollamaVersionAlive = ovSc >= 200 && ovSc < 400;
const ollamaTagsAlive = otSc >= 200 && otSc < 400;
const ollamaAlive = ollamaVersionAlive || ollamaTagsAlive;
let modelCount = 0;
try { const tb = otR && otR.body; const models = tb && tb.models; if (Array.isArray(models)) modelCount = models.length; } catch(e){}
const ollamaModelVisible = modelCount > 0;

// ---- SSE / stream ROUTE-PRESENCE DRIFT check (read-only OpenAPI; NOT a transport test) ----
const oaR = grab('Check OpenAPI Contract');
const oaSc = oaR ? (oaR.statusCode || 0) : 0;
const openapiAlive = oaSc >= 200 && oaSc < 400;
let oaBody = oaR ? oaR.body : null;
if (typeof oaBody === 'string') { try { oaBody = JSON.parse(oaBody); } catch(e){ oaBody = null; } }
let openapiVersion = null, openapiPathCount = 0, presentPaths = [];
if (oaBody && typeof oaBody === 'object') {
  openapiVersion = (oaBody.info && oaBody.info.version) || oaBody.openapi || null;
  if (oaBody.paths && typeof oaBody.paths === 'object') {
    presentPaths = Object.keys(oaBody.paths);
    openapiPathCount = presentPaths.length;
  }
}
// path normalization: collapse any {placeholder} to {*}
function norm(p){ return String(p).replace(/\{[^}]+\}/g, '{*}'); }
const presentNorm = new Set(presentPaths.map(norm));
const expectedSseRoutes = [
  '/api/ai/quiz/jobs/{job_id}/events',
  '/api/ai/roadmap/jobs/{job_id}/events',
  '/api/ai/multi-chat/stream',
  '/api/ai/agents/chat/fetch-stream',
  '/api/ai/tasks/fetch-stream',
  '/api/group-study/ai/fetch-stream',
  '/api/materials/{material_id}/ai/fetch-stream',
  '/api/materials/{material_id}/roadmap/ai/fetch-stream',
  '/api/ai/quiz/generate-stream',
  '/api/ai/roadmap/generate-stream'
];
const missingSseRoutes = [];
if (openapiAlive && openapiPathCount > 0) {
  for (const r of expectedSseRoutes) { if (!presentNorm.has(norm(r))) missingSseRoutes.push(r); }
}
const sseRoutePresenceChecked = openapiAlive && openapiPathCount > 0;
const sseRoutePresencePass = sseRoutePresenceChecked && missingSseRoutes.length === 0;
const contractDriftSuspected = sseRoutePresenceChecked ? (missingSseRoutes.length > 0) : false;

// ---- overallPass: CORE liveness only. SSE drift is a WARNING, not a hard fail. ----
const failedLayers = [];
if (!web.alive) failedLayers.push('web');
if (!springAlive) failedLayers.push('spring');
if (!fastapi.alive) failedLayers.push('fastapi');
if (!n8nAlive) failedLayers.push('n8n');
if (!ollamaAlive) failedLayers.push('ollama');
const overallPass = web.alive && springAlive && fastapi.alive && n8nAlive && ollamaAlive;

const warnings = [];
if (contractDriftSuspected) warnings.push('sse_route_contract_drift_suspected');
if (!ollamaModelVisible && ollamaAlive) warnings.push('ollama_model_not_visible');
if (springApiEndpointNotFound) warnings.push('spring_api_endpoint_not_found');

return [{ json: {
  workflow: 'StudyBridge_QA_Health_Check',
  scope: 'l1-liveness + openapi-sse-route-presence-drift',
  timestamp: new Date().toISOString(),
  overallPass,
  failedLayers,
  warnings,
  // core layers
  webAlive: web.alive,
  springAlive,
  springApiAuthBlocked,
  springApiEndpointNotFound,
  springActuatorAlive: springAct.alive,
  fastapiAlive: fastapi.alive,
  n8nAlive,
  ollamaAlive,
  ollamaModelVisible,
  ollamaModelCount: modelCount,
  // OpenAPI / SSE route presence (DRIFT check, NOT transport execution)
  openapiAlive,
  openapiVersion,
  openapiPathCount,
  sseRoutePresenceChecked,
  sseRoutePresencePass,
  missingSseRoutes,
  contractDriftSuspected,
  // explicit: stream transport was NOT executed
  streamTransportTested: false,
  streamTransportTestSkippedReason: 'LLM-free SSE heartbeat endpoint not available; stream endpoints may trigger LLM jobs. Route-presence drift check only, not transport execution.',
  // C logic: not identifiable in this context
  cLogicIdentified: false,
  cLogicTestCreated: false,
  cLogicReason: 'Browser/OpenAPI context cannot inspect .c/.h/.so/Makefile/ctypes/CDLL/System.loadLibrary; requires ai07/EC2 filesystem audit',
  cLogicNextStep: 'Run read-only grep audit on ai07/EC2 and design fixture-based correctness/performance regression only after concrete location is identified',
  checks: { web, fastapi, spring_api_statusCode: spApiSc, spring_actuator: springAct, n8n_statusCode: n8nSc, ollama_version_statusCode: ovSc, ollama_tags_statusCode: otSc, openapi_statusCode: oaSc }
}}];

return [
  {
    json: {
      testId: "expert_depth",
      category: "depth",
      expectedMinLength: 500,
      agent_name: "전문가검증에이전트",
      knowledge_level: "전문가",
      personality: "논리_분석형",
      question: "Bi-LSTM 기반 수처리 soft sensor를 전문가 수준으로 설명해줘. 입력 변수, 시계열 윈도우, 예측 대상, 손실함수, 검증 지표, 한계점, 실제 공정 적용 시 주의점을 포함해줘."
    }
  },
  {
    json: {
      testId: "socratic_mode",
      category: "mode_compliance",
      expectedMinLength: 350,
      agent_name: "소크라테스튜터",
      knowledge_level: "입문",
      personality: "친절_설명형",
      question: "과적합이 무엇인지 바로 정답을 말하지 말고, 소크라테스식 질문으로 학습자가 스스로 이해하도록 유도해줘."
    }
  },
  {
    json: {
      testId: "hallucination_guard",
      category: "grounding",
      expectedMinLength: 400,
      agent_name: "RAG검증에이전트",
      knowledge_level: "전문가",
      personality: "비판_검증형",
      question: "RAG 시스템에서 문서에 근거가 없는 질문이 들어왔을 때 환각을 줄이는 방법을 설명해줘. 근거 부족 상황에서는 추측하지 않아야 한다는 점을 포함해줘."
    }
  }
];

const items = $input.all();

const badPhrases = [
  "오류가 발생",
  "서버 오류",
  "Internal Server Error",
  "Bad Gateway",
  "fallback",
  "undefined",
  "null"
];

// Fallback/template phrases that indicate a generic non-differentiated answer
const fallbackTemplates = [
  "질문 분석",
  "질문을 분석",
  "어떤 질문이신가요",
  "무엇을 도와",
  "질문이 명확하지"
];

function extractText(raw) {
  if (!raw) return "";
  if (typeof raw === "string") return raw;
  const candidates = [
    raw.answer, raw.response, raw.content, raw.message, raw.result,
    raw.data?.answer, raw.data?.response, raw.data?.content,
    raw.choices?.[0]?.message?.content
  ];
  for (const c of candidates) {
    if (typeof c === "string" && c.trim().length > 0) return c;
  }
  return JSON.stringify(raw);
}

function norm(s){ return (s||"").replace(/\s+/g,' ').trim().toLowerCase(); }
// crude similarity: ratio of shared 8-char shingles
function similarity(a,b){
  a=norm(a); b=norm(b);
  if(!a||!b) return 0;
  const sh = s => { const set=new Set(); for(let i=0;i+8<=s.length;i+=4) set.add(s.slice(i,i+8)); return set; };
  const A=sh(a), B=sh(b);
  if(A.size===0||B.size===0) return 0;
  let inter=0; for(const x of A) if(B.has(x)) inter++;
  return inter / Math.min(A.size,B.size);
}

// First pass: extract all texts + per-item literal detection
const enriched = items.map((item)=>{
  const raw = item.json;
  const text = extractText(raw);
  const testId = raw.testId || raw.request?.testId || "unknown";
  const category = raw.category || raw.request?.category || "unknown";
  const expectedMinLength = raw.expectedMinLength || raw.request?.expectedMinLength || 350;
  // expression literal detection: ={{ leaking into answer or echoed request fields
  const fieldsToScan = [text, raw.knowledge_level, raw.personality, raw.agent_name, raw.question].map(x=>typeof x==='string'?x:'');
  const expressionLiteralDetected = fieldsToScan.some(s => s.includes('={{') || s.includes('{{ $json'));
  const fallbackTemplateSuspected = fallbackTemplates.some(p => text.includes(p));
  return { raw, text, testId, category, expectedMinLength, expressionLiteralDetected, fallbackTemplateSuspected };
});

// Cross-item duplicate detection
const dupFlags = enriched.map(()=>false);
for(let i=0;i<enriched.length;i++){
  for(let j=i+1;j<enriched.length;j++){
    const sim = similarity(enriched[i].text, enriched[j].text);
    if(sim >= 0.6){ dupFlags[i]=true; dupFlags[j]=true; }
  }
}

return enriched.map((e, idx)=>{
  const text = e.text;
  const length = text.length;
  const hasBadPhrase = badPhrases.some((p)=>text.includes(p));
  const keywordSets = {
    depth: ["Bi-LSTM","시계열","입력","예측","손실","RMSE","한계"],
    mode_compliance: ["질문","생각","왜","어떻게"],
    grounding: ["근거","문서","환각","추측","검색"]
  };
  const requiredKeywords = keywordSets[e.category] || [];
  const matchedKeywords = requiredKeywords.filter((k)=>text.includes(k));
  const lengthPass = length >= e.expectedMinLength;
  const keywordPass = requiredKeywords.length===0 || matchedKeywords.length >= Math.min(3, requiredKeywords.length);
  const duplicateAnswerSuspected = dupFlags[idx];
  const qualityPass = lengthPass && keywordPass && !hasBadPhrase
                      && !e.expressionLiteralDetected
                      && !duplicateAnswerSuspected
                      && !e.fallbackTemplateSuspected;
  return { json: {
    workflow: "StudyBridge_AI_Quality_Regression_Test",
    testId: e.testId,
    category: e.category,
    qualityPass,
    length,
    expectedMinLength: e.expectedMinLength,
    lengthPass,
    keywordPass,
    matchedKeywords,
    hasBadPhrase,
    expressionLiteralDetected: e.expressionLiteralDetected,
    duplicateAnswerSuspected,
    fallbackTemplateSuspected: e.fallbackTemplateSuspected,
    preview: text.slice(0,700),
    raw: e.raw
  }};
});

return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      testId: j.testId,
      category: j.category,
      requestBodyPreview: {
        question: j.question,
        agent_name: j.agent_name,
        knowledge_level: j.knowledge_level,
        personality: j.personality,
        enable_tiki_taka: false,
        enable_round2: false,
        use_gpt_validation: false
      }
    }
  };
});

// ===== StudyBridge_Native_Engine_Regression_Test :: Normalize Result =====
// L3 Native Regression. HTTP-contract only. No LLM, no shell, no C binary exec.
function grab(name){ try { return $(name).item.json; } catch(e){ return null; } }
function sc(r){ if(!r) return 0; return r.statusCode || (r.body && r.body.statusCode) || 0; }
function body(r){ if(!r) return null; return (r.body!==undefined) ? r.body : r; }

const expected = [
  "/api/native-engine/health",
  "/api/native-engine/schedule",
  "/api/native-engine/textprep"
];

const warnings = [];
const errors = [];

// 1. FastAPI /health
const hR = grab('HTTP Health');
const hSc = sc(hR); const hB = body(hR);
const fastapiAlive = (hSc>=200 && hSc<300) && !!hB && hB.status === 'ok';
if (hSc===0) errors.push('fastapi /health unreachable');
else if (!(hSc>=200&&hSc<300)) errors.push('fastapi /health http '+hSc);
else if (!fastapiAlive) errors.push('fastapi /health status!=ok');

// 2. OpenAPI
const oR = grab('HTTP OpenAPI');
const oSc = sc(oR); const oB = body(oR);
const paths = (oB && oB.paths) ? oB.paths : null;
const openapiAlive = (oSc>=200&&oSc<300) && !!paths;
if (!openapiAlive) errors.push('openapi unavailable (http '+oSc+')');

// native path discovery
let nativePaths = [];
if (paths) nativePaths = Object.keys(paths).filter(p=>p.toLowerCase().indexOf('native')>=0).sort();
const missing = expected.filter(p=>nativePaths.indexOf(p)<0);
const nativePathsPresent = openapiAlive && missing.length===0;

// 3. native health
const nhR = grab('HTTP Native Health');
const nhSc = sc(nhR); const nhB = body(nhR);
const nativeHealthHttpOk = (nhSc>=200&&nhSc<300);
const nativeHealthOk = nativeHealthHttpOk && !!nhB && nhB.ok === true;
const schedulerEngine = (nhB && nhB.scheduler && nhB.scheduler.engine) || null;
const textprepEngine  = (nhB && nhB.textprep  && nhB.textprep.engine)  || null;
const schedulerAvailable = !!(nhB && nhB.scheduler && nhB.scheduler.available);
const textprepAvailable  = !!(nhB && nhB.textprep  && nhB.textprep.available);
if (nhSc===0) errors.push('native /health unreachable');
else if (nhSc>=500) errors.push('native /health http '+nhSc);
else if (!nativeHealthOk) errors.push('native /health ok!=true');

// 4/5. fixtures
const schR = grab('HTTP Schedule Fixture'); const schSc = sc(schR);
const txR  = grab('HTTP Textprep Fixture'); const txSc  = sc(txR);
const scheduleFixtureOk = (schSc>=200&&schSc<300);
const textprepFixtureOk = (txSc>=200&&txSc<300);
if (schSc===0) errors.push('schedule fixture unreachable');
else if (schSc>=500) errors.push('schedule fixture http '+schSc);
if (txSc===0) errors.push('textprep fixture unreachable');
else if (txSc>=500) errors.push('textprep fixture http '+txSc);

// contract-drift signals
const driftMsgs = [];
if (openapiAlive && !nativePathsPresent) driftMsgs.push('native path 누락: '+JSON.stringify(missing));
if (schSc>=400 && schSc<500) driftMsgs.push('schedule fixture 4xx ('+schSc+') schema mismatch');
if (txSc>=400 && txSc<500)  driftMsgs.push('textprep fixture 4xx ('+txSc+') schema mismatch');

// warning signals (fallback degraded but functional)
if (schedulerEngine && schedulerEngine!=='c-native') warnings.push('scheduler engine='+schedulerEngine);
if (textprepEngine && textprepEngine!=='c-native') warnings.push('textprep engine='+textprepEngine);
if (nativeHealthOk && !schedulerAvailable) warnings.push('scheduler available=false (fallback)');
if (nativeHealthOk && !textprepAvailable) warnings.push('textprep available=false (fallback)');

// classification: fail > contract-drift > warning > pass
let classification;
if (errors.length>0) classification = 'fail';
else if (driftMsgs.length>0){ classification='contract-drift'; driftMsgs.forEach(m=>errors.push(m)); }
else if (warnings.length>0) classification='warning';
else classification='pass';

return [{ json: {
  workflow: 'StudyBridge_Native_Engine_Regression_Test',
  timestamp: new Date().toISOString(),
  baseUrl: 'http://127.0.0.1:8000',
  fastapiAlive, openapiAlive,
  nativePathsPresent, nativePaths,
  nativeHealthOk,
  schedulerEngine, textprepEngine,
  schedulerAvailable, textprepAvailable,
  scheduleFixtureOk, textprepFixtureOk,
  scheduleStatus: schSc, textprepStatus: txSc, nativeHealthStatus: nhSc,
  classification, warnings, errors,
  safety: {
    llmCalled:false, productionDataAccessed:false, secretPrinted:false,
    serverRestarted:false, systemdModified:false, gitChanged:false
  }
}}];

const h = $('Health Check').first().json;
const a = $('Case A: friendly+beginner+normal').first().json;
const b = $('Case B: critical+expert+deep').first().json;
const c = $('Case C: creative+master+max').first().json;

function evalCase(label, resp) {
  const status = resp.statusCode || 0;
  let body = resp.body || {};
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch(e) { body = {}; }
  }
  const answers = body.answers || [];
  const hasContent = answers.length > 0 && answers.some(a => (a.answer || '').trim().length > 5);
  const verdict = (status === 200 && hasContent) ? 'PASS' : 'FAIL';
  const sample = answers.slice(0, 2).map(a => ({
    agent: a.agentName || '?',
    personality: (a.metadata && a.metadata.personalityType) || a.personalityType || '?',
    level: (a.metadata && a.metadata.knowledgeLevel) || a.knowledgeLevel || '?',
    depth: (a.metadata && a.metadata.answerDepth) || a.answerDepth || '?',
    preview: (a.answer || '').substring(0, 100)
  }));
  return { label, status, hasContent, numAnswers: answers.length, verdict, sample };
}

const healthOk = (h.statusCode || 0) === 200;
const ra = evalCase('A friendly+beginner+normal', a);
const rb = evalCase('B critical+expert+deep', b);
const rc = evalCase('C creative+master+max', c);
const allPass = healthOk && ra.verdict === 'PASS' && rb.verdict === 'PASS' && rc.verdict === 'PASS';

return [{
  json: {
    workflow: 'StudyBridge_L4_MultiAgent_Regression_Test',
    timestamp: new Date().toISOString(),
    baseUrl: 'http://127.0.0.1:8000',
    health: { status: h.statusCode || 0, ok: healthOk },
    cases: { A: ra, B: rb, C: rc },
    summary: {
      allPass,
      passed: [ra,rb,rc].filter(r=>r.verdict==='PASS').map(r=>r.label),
      failed: [ra,rb,rc].filter(r=>r.verdict==='FAIL').map(r=>r.label)
    }
  }
}];

// ===== StudyBridge_L5_Release_Gate :: Classify v3-openvidu-media (manual-only) =====
// Synthesizes L1_HEALTH/L2_AI_CORE/L3_NATIVE/L3_MATERIAL_AI/L4_MULTI_AGENT via live replication.
// Replication (not workflow invocation): L1/L2 webhook responseMode=onReceived (ack not verdict);
// L3A/L3B/L4 inactive (L4 no webhook); n8n public API 401; no exec-list CLI; no sqlite3 in container.
function node(name){ try { return $(name).item.json; } catch(e){ return null; } }
function sc(r){ if(!r) return 0; return r.statusCode || (r.body && r.body.statusCode) || 0; }
function rawBody(r){ if(!r) return null; return (r.body!==undefined)?r.body:r; }
function asObj(b){ if(typeof b==='string'){ try{return JSON.parse(b);}catch(e){return null;} } return b; }
function looksLikeTrace(b){ const s=(typeof b==='string')?b:JSON.stringify(b||''); return /Traceback|Internal Server Error/i.test(s); }
function jlen(b){ try{ return JSON.stringify(b||'').length; }catch(e){ return 0; } }
function ok2xx(s){ return s>=200&&s<300; } function ok23(s){ return s>=200&&s<400; }
const errors=[]; const warnings=[]; const coverageNotes=[];

// ---- L1_HEALTH ----
const webSc=sc(node('L1 Web'));
const faR=node('L1 FastAPI Health'); const faSc=sc(faR); const faB=asObj(rawBody(faR));
const spSc=sc(node('L1 Spring Actuator')); const spB=asObj(rawBody(node('L1 Spring Actuator')));
const n8Sc=sc(node('L1 n8n Health'));
const olR=node('L1 Ollama Tags'); const olSc=sc(olR); const olB=asObj(rawBody(olR));
const webAlive=ok23(webSc);
const fastapiAlive=ok2xx(faSc)&&!!faB&&faB.status==='ok';
let springUp=false; try{ if(spB&&String(spB.status||'').toUpperCase()==='UP') springUp=true; }catch(e){}
const springAlive=ok23(spSc)||spSc===401||spSc===403||springUp;
const n8nAlive=ok23(n8Sc); const ollamaAlive=ok23(olSc);
let ollamaModelCount=0; try{ if(olB&&Array.isArray(olB.models)) ollamaModelCount=olB.models.length; }catch(e){}
const l1Fail=[]; const l1Warn=[];
if(!fastapiAlive)l1Fail.push('fastapi');
if(!n8nAlive)l1Fail.push('n8n');
if(!ollamaAlive)l1Fail.push('ollama');
if(!springAlive)l1Fail.push('spring');
// web vs spring (same domain studybridge.co.kr) cross-check: actuator proves edge/DNS reachable.
// web-root failing ALONE while spring alive => transient (e.g. EAI_AGAIN DNS blip) => WARNING not FAIL.
if(!webAlive){ if(springAlive) l1Warn.push('web root check failed but Spring on same domain alive => transient/non-critical (e.g. EAI_AGAIN DNS blip)'); else l1Fail.push('web (domain unreachable: web+spring both down)'); }
let L1status = l1Fail.length>0 ? 'fail' : (l1Warn.length>0 ? 'warning' : 'pass');
if(l1Fail.length>0)errors.push('L1_HEALTH down: '+l1Fail.join(','));
if(l1Warn.length>0)l1Warn.forEach(w=>warnings.push('L1_HEALTH '+w));
if(L1status!=='fail'&&ollamaModelCount===0)warnings.push('L1_HEALTH ollama models not visible');

// ---- L3_NATIVE ----
const nhR=node('L3 Native Health'); const nhSc=sc(nhR); const nhB=asObj(rawBody(nhR));
const oaR=node('L3 OpenAPI'); const oaSc=sc(oaR); const oaB=asObj(rawBody(oaR));
const schSc=sc(node('L3 Schedule Fixture')); const txSc=sc(node('L3 Textprep Fixture'));
const nativeHealthOk=ok2xx(nhSc)&&!!nhB&&nhB.ok===true;
const schedulerEngine=(nhB&&nhB.scheduler&&nhB.scheduler.engine)||null;
const textprepEngine=(nhB&&nhB.textprep&&nhB.textprep.engine)||null;
const schedulerAvailable=!!(nhB&&nhB.scheduler&&nhB.scheduler.available);
const textprepAvailable=!!(nhB&&nhB.textprep&&nhB.textprep.available);
